// Generated by scripts/build-portable.mjs. Code assets only; no reports are cached here.
const PREFIX='secheron-reports-'+encodeURIComponent(new URL(self.registration.scope).pathname)+'-';
const CACHE=PREFIX+'68a49896528df4ce';
const ASSETS=["./","./index.html","./manifest.webmanifest","./icon-192.png","./icon-512.png"];
const rootURL=new URL('./',self.registration.scope).href;
self.addEventListener('install',event=>event.waitUntil((async()=>{
 try{const cache=await caches.open(CACHE);await cache.addAll(ASSETS.map(p=>new Request(new URL(p,rootURL).href,{cache:'reload'})));}
 catch(error){await caches.delete(CACHE);throw error;}
})()));
self.addEventListener('activate',event=>event.waitUntil((async()=>{for(const key of await caches.keys()){if(key.startsWith(PREFIX)&&key!==CACHE)await caches.delete(key);}await self.clients.claim();})()));
self.addEventListener('message',event=>{if(event.data?.type==='ACTIVATE_UPDATE')self.skipWaiting();});
self.addEventListener('fetch',event=>{
 const url=new URL(event.request.url);if(event.request.method!=='GET'||url.origin!==new URL(rootURL).origin||!url.pathname.startsWith(new URL(rootURL).pathname))return;
 event.respondWith((async()=>{const cache=await caches.open(CACHE);if(event.request.mode==='navigate'){const page=await cache.match(new URL('./index.html',rootURL).href);if(page)return page;}
 const cached=await cache.match(event.request,{ignoreSearch:true});if(cached)return cached;return fetch(event.request);})());
});
